"""Conservative temporary media cleanup with cross-process file ownership locks."""
from __future__ import annotations

import json
import os
import re
import stat
import shutil
import time
import uuid
from contextlib import contextmanager
from dataclasses import dataclass, field
from pathlib import Path

MARKER = ".tgdl-owner.lock"
SIGNATURE = "tgdl-owned-v1"
CANDIDATE_PREFIXES = ("tgdl-", "tgdl-publish-")
PEER_DOWNLOADS_DIR = "tgdl-by-peer"
# The historical unmarked names were generated by TemporaryDirectory and
# time.time_ns(); an app prefix alone is not evidence a file is disposable.
_LEGACY_CACHE = re.compile(r"tgdl-[a-z0-9_]{8}")
_LEGACY_PUBLISH = re.compile(r"\.tgdl-publishing-\d{8}_\d+-\d{16,}\.[a-zA-Z0-9]{1,10}")
_LEGACY_PART = re.compile(r"(?:data|normal)\.[a-zA-Z0-9]{1,10}")


def _lock(file, *, nonblocking=True):
    file.seek(0)
    if os.name == "nt":
        import msvcrt
        try:
            msvcrt.locking(file.fileno(), msvcrt.LK_NBLCK if nonblocking else msvcrt.LK_LOCK, 1)
        except OSError:
            return False
    else:
        import fcntl
        try:
            fcntl.flock(file.fileno(), fcntl.LOCK_EX | (fcntl.LOCK_NB if nonblocking else 0))
        except BlockingIOError:
            return False
    return True


def _unlock(file):
    file.seek(0)
    if os.name == "nt":
        import msvcrt
        msvcrt.locking(file.fileno(), msvcrt.LK_UNLCK, 1)
    else:
        import fcntl
        fcntl.flock(file.fileno(), fcntl.LOCK_UN)


@contextmanager
def own_temporary(directory: Path):
    """Hold an OS lock for the entire lifetime of a temporary directory."""
    directory = Path(directory)
    marker = directory / MARKER
    with marker.open("x+b") as handle:
        handle.write(bytes([0]))
        handle.flush()
        if not _lock(handle):
            raise RuntimeError("Unable to lock new download temporary directory")
        handle.seek(1)
        handle.write(json.dumps({
            "signature": SIGNATURE,
            "pid": os.getpid(),
            "created": time.time(),
            "nonce": uuid.uuid4().hex,
        }).encode("utf-8"))
        handle.flush()
        try:
            yield
        finally:
            _unlock(handle)


def _valid_marker(handle):
    try:
        handle.seek(1)
        entry = json.loads(handle.read().decode("utf-8"))
        return entry.get("signature") == SIGNATURE and bool(entry.get("nonce"))
    except (OSError, UnicodeError, ValueError, AttributeError):
        return False


def _size(directory: Path):
    total = 0
    for root, dirs, files in os.walk(directory, followlinks=False):
        dirs[:] = [d for d in dirs if not (Path(root) / d).is_symlink()]
        for name in files:
            try:
                file = Path(root) / name
                if not file.is_symlink():
                    total += file.stat().st_size
            except OSError:
                continue
    return total


@dataclass
class CleanupResult:
    deleted: int = 0
    bytes_freed: int = 0
    active: int = 0
    legacy: list[Path] = field(default_factory=list)
    failed: list[str] = field(default_factory=list)

    def summary(self) -> str:
        return (
            f"[缓存清理] 清理 {self.deleted} 项，释放 {self.bytes_freed / 1024**3:.2f} GiB；"
            f"正在使用 {self.active} 项，未识别旧临时文件 {len(self.legacy)} 项，"
            f"失败 {len(self.failed)} 项"
        )


def is_link_or_reparse_point(path: Path) -> bool:
    """Check Windows junctions on all supported Python versions without following."""
    try:
        entry = path.lstat()
    except (FileNotFoundError, NotADirectoryError):
        return False
    return stat.S_ISLNK(entry.st_mode) or bool(
        getattr(entry, "st_file_attributes", 0) & stat.FILE_ATTRIBUTE_REPARSE_POINT
    )


def _plain_directory(path: Path) -> bool:
    return not is_link_or_reparse_point(path) and path.is_dir()


def _candidates(ssd_dir: Path | None, download_dir: Path | None):
    parents = set()
    base = Path(download_dir) if download_dir is not None else None
    if base is not None and _plain_directory(base):
        # Never treat the downloads root as a staging directory. Its immediate
        # children are channel folders, whose names come from Telegram.
        channels = list(base.iterdir())
        namespace = base / PEER_DOWNLOADS_DIR
        if _plain_directory(namespace):
            channels.extend(namespace.iterdir())
        for channel in channels:
            if _plain_directory(channel):
                for media in ("photos", "videos", "parsed/direct", "parsed/torrents"):
                    folder = channel
                    for component in media.split("/"):
                        folder = folder / component
                        if not _plain_directory(folder):
                            break
                    else:
                        parents.add(folder.resolve())
    if ssd_dir is not None and _plain_directory(Path(ssd_dir)):
        staging = Path(ssd_dir).resolve()
        if base is None or staging != base.resolve():
            parents.add(staging)
    for parent in sorted(parents):
        for child in parent.iterdir():
            if is_link_or_reparse_point(child):
                continue
            if _plain_directory(child) and child.name.startswith(CANDIDATE_PREFIXES):
                yield child
            elif child.is_file() and _LEGACY_PUBLISH.fullmatch(child.name):
                yield child


def _legacy_parts(candidate: Path) -> tuple[Path, ...]:
    if is_link_or_reparse_point(candidate):
        return ()
    if candidate.is_file():
        info = candidate.stat(follow_symlinks=False)
        return (candidate,) if _LEGACY_PUBLISH.fullmatch(candidate.name) and info.st_nlink == 1 else ()
    if not _plain_directory(candidate) or not _LEGACY_CACHE.fullmatch(candidate.name):
        return ()
    # Never recursively remove an unmarked directory. Old staged downloads
    # may have left data and/or a normal fallback, but no evidence of
    # ownership exists for directories, links or other filenames inside it.
    entries = tuple(candidate.iterdir())
    for part in entries:
        if not _LEGACY_PART.fullmatch(part.name) or is_link_or_reparse_point(part):
            return ()
        info = part.stat(follow_symlinks=False)
        if not stat.S_ISREG(info.st_mode) or info.st_nlink != 1:
            return ()
    return entries


def staging_orphan_bytes(folder: Path) -> int:
    """Count staging data, not completed download directories with similar names."""
    if not _plain_directory(folder) or folder.name == PEER_DOWNLOADS_DIR:
        return 0
    marker = folder / MARKER
    if marker.is_symlink():
        return 0
    if marker.is_file():
        with marker.open("rb") as handle:
            return _size(folder) if _valid_marker(handle) else 0
    return sum(part.stat(follow_symlinks=False).st_size for part in _legacy_parts(folder))


def inspect_cleanup(ssd_dir: Path | None, download_dir: Path | None, *,
                    approved_legacy: set[Path] | None = None) -> CleanupResult:
    """Remove abandoned owned work and only explicitly approved legacy paths."""
    result = CleanupResult()
    try:
        candidates = list(_candidates(ssd_dir, download_dir))
    except OSError as exc:
        result.failed.append(f"扫描目录失败: {exc}")
        return result
    for candidate in candidates:
        marker = candidate / MARKER if candidate.is_dir() else None
        if is_link_or_reparse_point(candidate):
            continue
        if marker is not None and (is_link_or_reparse_point(marker) or
                                   (marker.exists() and not marker.is_file())):
            continue
        if marker is None or not marker.is_file():
            try:
                parts = _legacy_parts(candidate)
                if not parts:
                    continue
                if approved_legacy is None or candidate not in approved_legacy:
                    result.legacy.append(candidate)
                    continue
                length = sum(part.stat(follow_symlinks=False).st_size for part in parts)
                for part in parts:
                    part.unlink()
                if parts != (candidate,):
                    candidate.rmdir()
                result.deleted += 1
                result.bytes_freed += length
            except OSError as exc:
                result.failed.append(f"{candidate}: {exc}")
            continue
        try:
            with marker.open("r+b") as lock_handle:
                if not _valid_marker(lock_handle):
                    continue
                if not _lock(lock_handle):
                    result.active += 1
                    continue
                try:
                    length = _size(candidate)
                    # Keep the locked marker open while removing the files.
                    # Windows refuses removal of opened files; explicitly
                    # delete other contents, then release marker before rmdir.
                    for child in candidate.iterdir():
                        if child == marker:
                            continue
                        if child.is_symlink() or child.is_file():
                            child.unlink()
                        elif child.is_dir():
                            shutil.rmtree(child)
                    result.bytes_freed += length
                    result.deleted += 1
                finally:
                    _unlock(lock_handle)
            marker.unlink()
            candidate.rmdir()
        except OSError as exc:
            result.failed.append(f"{candidate}: {exc}")
    return result
